/**
 * Environment dressing: one free CC0 asset pack per island (see
 * Worlds_Edge_Free_3D_Environment_Packs.pdf), laid out deterministically so the
 * server and every client agree on where things are. Large props (trees,
 * rocks, towers, huts, wrecks) add invisible box colliders to the world; small
 * props (grass, flowers, barrels) are visual only.
 *
 * Model sizes come from `env-models.ts`, generated by `npm run build-env` from
 * the downloaded packs. A group whose models aren't built yet is skipped, and an
 * area whose own pack isn't available uses its `standIn` groups instead.
 */
import { RIM_Z, SEA_LEVEL } from "./constants.ts";
import { ENV_MODELS } from "./env-models.ts";
import type { Box } from "./world.ts";
import { allSkinModels, skinPlacements } from "./skins.ts";

export interface Placement {
  /** "<pack>/<model>" — the client loads /env/<pack>/<model>.glb */
  model: string;
  x: number; y: number; z: number;
  rotY: number;
  /** Scale per axis (props are uniform; block skins stretch to fit). */
  sx: number; sy: number; sz: number;
  /** Solid props get an invisible box collider. */
  collide?: "full" | "trunk";
}

export interface DressedArea {
  id: string;
  name: string;
  /** The pack actually used (the area's own, or its stand-in). */
  pack: string;
  /** The pack this area is meant to use. */
  plannedPack: string;
  center: { x: number; y: number; z: number };
  /** Load the area's models when the camera is within this distance of `center`. */
  loadRadius: number;
  /** Terrain and buildings: loaded at start and always drawn (props load by distance). */
  always?: boolean;
  placements: Placement[];
}

type Where = "top" | "shore" | "water";

interface Group {
  models: string[];
  count: number;
  /** Target size in metres (the model is scaled uniformly): its height, or with fit "longest" its longest side. */
  height: [number, number];
  /** Flat or long models (rocks, logs) are sized by their longest side instead of their height. */
  fit?: "longest";
  collide?: "full" | "trunk";
  where?: Where;
  /** Minimum distance to other placements (metres). */
  spacing?: number;
}

interface Surface { x0: number; x1: number; z0: number; z1: number; y: number }

interface AreaSpec {
  id: string;
  name: string;
  pack: string;
  surface: Surface;
  /** For shore and water placements: the island's outline and how far out to go. */
  island?: { x: number; z: number; half: number };
  waterReach?: number;
  groups: Group[];
  /** Used when `pack` hasn't been downloaded yet (Google Drive quota, itch.io). */
  standIn?: { pack: string; groups: Group[] };
}

