const dk = (...names: string[]) => names.map((n) => `kenney-modular-dungeon-kit/${n}`);

/** Island tops in the Broken Isles (mirrors world.ts). Grass surface = top + 0.8. */
export const ISLES = [
  { x: 160, z: -300, top: 18, size: 60 },
  { x: 60, z: -420, top: 40, size: 34 },
  { x: -120, z: -380, top: 26, size: 46 },
  { x: -40, z: -600, top: 60, size: 30 },
  { x: 140, z: -700, top: 32, size: 52 },
  { x: -180, z: -820, top: 48, size: 40 },
  { x: 30, z: -980, top: 22, size: 70 },
  { x: -90, z: -1160, top: 36, size: 38 },
  { x: 120, z: -1240, top: 54, size: 28 },
];

function isleSurface(i: number): Surface {
  const s = ISLES[i];
  const half = (s.size * 0.92) / 2 - 2;
  return { x0: s.x - half, x1: s.x + half, z0: s.z - half, z1: s.z + half, y: s.top + 0.8 };
}
const isleOutline = (i: number) => ({ x: ISLES[i].x, z: ISLES[i].z, half: ISLES[i].size / 2 });

