// --- Generation --------------------------------------------------------------------

function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const hash = (s: string) => [...s].reduce((h, c) => (Math.imul(h, 31) + c.charCodeAt(0)) | 0, 7);

/** Places the game keeps clear: spawn, shrine, gate, enemy homes (metres). */
const KEEP_CLEAR = [
  { x: -60, z: 30, r: 24 }, // training yard and spawn
  { x: -45, z: 30, r: 8 }, // shrine
  { x: 0, z: -1484, r: 12 }, // Colossus gate
  { x: 0, z: -64, r: 14 }, // terrace stairs
  { x: 0, z: 20, r: 28 }, // plaza
  { x: -120, z: -380, r: 14 }, // Hullbreaker
  { x: 0, z: 84, r: 16 }, // Colossus entry platform (arena)
];

function blocked(base: Box[], x: number, y: number, z: number, margin: number) {
  for (const b of base) {
    if (b.minY <= y + 0.05 && b.maxY > y + 0.05 && x > b.minX - margin && x < b.maxX + margin && z > b.minZ - margin && z < b.maxZ + margin) return true;
  }
  return false;
}

function groundAt(base: Box[], x: number, z: number, fromY: number) {
  let best = -Infinity;
  for (const b of base) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.maxY <= fromY + 0.01 && b.maxY > best) best = b.maxY;
  }
  return best;
}

export function packAvailable(pack: string) {
  for (const id in ENV_MODELS) if (id.startsWith(`${pack}/`)) return true;
  return false;
}

function layout(spec: AreaSpec, base: Box[]): DressedArea {
  const own = packAvailable(spec.pack);
  const pack = own || !spec.standIn ? spec.pack : spec.standIn.pack;
  const groups = own || !spec.standIn ? spec.groups : spec.standIn.groups;
  const r = rng(hash(spec.id));
  const placed: Placement[] = [];
  const s = spec.surface;

  for (const g of groups) {
    const models = g.models.filter((m) => ENV_MODELS[m]);
    if (!models.length) continue;
    const where = g.where ?? "top";
    let made = 0;
    for (let attempt = 0; attempt < g.count * 25 && made < g.count; attempt++) {
      let x: number, z: number, y: number;
      if (where === "top") {
        x = s.x0 + r() * (s.x1 - s.x0);
        z = s.z0 + r() * (s.z1 - s.z0);
        y = groundAt(base, x, z, s.y + 0.5);
        if (Math.abs(y - s.y) > 0.6 || blocked(base, x, y, z, 1)) continue;
      } else if (where === "shore" && spec.island) {
        // Just outside the island's cliffs, standing in the shallows.
        const isl = spec.island, out = 2 + r() * 6;
        const side = Math.floor(r() * 4), t = (r() * 2 - 1) * isl.half;
        x = isl.x + (side === 0 ? isl.half + out : side === 1 ? -isl.half - out : t);
        z = isl.z + (side === 2 ? isl.half + out : side === 3 ? -isl.half - out : t);
        y = SEA_LEVEL - 0.5;
        if (blocked(base, x, y + 0.6, z, 1)) continue;
      } else {
        // Open water: near the island if there is one, else anywhere in the area.
        if (spec.island) {
          const isl = spec.island, a = r() * Math.PI * 2, d = isl.half + 8 + r() * (spec.waterReach ?? 20);
          x = isl.x + Math.cos(a) * d; z = isl.z + Math.sin(a) * d;
        } else {
          x = s.x0 + r() * (s.x1 - s.x0); z = s.z0 + r() * (s.z1 - s.z0);
        }
        y = SEA_LEVEL - 0.2;
        if (groundAt(base, x, z, 200) > -50 || blocked(base, x, y + 0.5, z, 6)) continue;
      }
      if (KEEP_CLEAR.some((k) => Math.hypot(x - k.x, z - k.z) < k.r)) continue;
      const spacing = g.spacing ?? 3;
      if (placed.some((p) => Math.hypot(p.x - x, p.z - z) < spacing)) continue;
      const model = models[Math.floor(r() * models.length)];
      const info = ENV_MODELS[model];
      const height = g.height[0] + r() * (g.height[1] - g.height[0]);
      const dims = [0, 1, 2].map((k) => info.max[k] - info.min[k]);
      const scale = height / Math.max(0.01, g.fit === "longest" ? Math.max(...dims) : dims[1]);
      // Colliding props snap to right angles so their box colliders stay exact.
      const rotY = g.collide === "full" ? Math.floor(r() * 4) * (Math.PI / 2) : r() * Math.PI * 2;
      placed.push({ model, x, y: y - info.min[1] * scale, z, rotY, sx: scale, sy: scale, sz: scale, ...(g.collide ? { collide: g.collide } : {}) });
      made++;
    }
  }

  const cx = (s.x0 + s.x1) / 2, cz = (s.z0 + s.z1) / 2;
  const radius = Math.hypot(s.x1 - s.x0, s.z1 - s.z0) / 2;
  return {
    id: spec.id, name: spec.name, pack, plannedPack: spec.pack,
    center: { x: cx, y: s.y, z: cz },
    loadRadius: radius + 650,
    placements: placed,
  };
}

/** Invisible colliders for the props that should be solid. */
function colliders(area: DressedArea): Box[] {
  const out: Box[] = [];
  for (const p of area.placements) {
    if (!p.collide) continue;
    const info = ENV_MODELS[p.model];
    const sx = (info.max[0] - info.min[0]) * p.sx, sz = (info.max[2] - info.min[2]) * p.sz;
    const h = (info.max[1] - info.min[1]) * p.sy;
    const cx = p.x + ((info.max[0] + info.min[0]) / 2) * p.sx, cz = p.z + ((info.max[2] + info.min[2]) / 2) * p.sz;
    const quarter = Math.round(p.rotY / (Math.PI / 2)) % 2 === 1;
    const [w, d] = quarter ? [sz, sx] : [sx, sz];
    const base = p.y + info.min[1] * p.sy;
    if (p.collide === "trunk") {
      const t = Math.max(0.5, Math.min(w, d) * 0.18);
      out.push({ minX: p.x - t / 2, maxX: p.x + t / 2, minZ: p.z - t / 2, maxZ: p.z + t / 2, minY: base, maxY: base + h * 0.75, color: "#000000", region: "isles", hidden: true });
    } else {
      out.push({ minX: cx - w / 2, maxX: cx + w / 2, minZ: cz - d / 2, maxZ: cz + d / 2, minY: base, maxY: base + h, color: "#000000", region: "isles", hidden: true });
    }
  }
  return out;
}

/**
 * Terrain and buildings: every skinned block drawn with pack models, grouped by
 * the area it sits in (so each group culls on its own) and always loaded.
 */
function terrain(base: Box[], areas: AreaSpec[]): DressedArea[] {
  const groups = new Map<string, DressedArea>();
  for (const b of base) {
    if (!b.skin) continue;
    const cx = (b.minX + b.maxX) / 2, cz = (b.minZ + b.maxZ) / 2;
    const home = areas.find((a) => a.id !== "ocean" && cx > a.surface.x0 - 40 && cx < a.surface.x1 + 40 && cz > a.surface.z0 - 40 && cz < a.surface.z1 + 40);
    const id = `terrain:${home?.id ?? "world"}`;
    let g = groups.get(id);
    if (!g) {
      const c = home ? { x: (home.surface.x0 + home.surface.x1) / 2, y: home.surface.y, z: (home.surface.z0 + home.surface.z1) / 2 } : { x: 0, y: 0, z: 0 };
      g = { id, name: `${home?.name ?? "World"} terrain`, pack: b.skin.model.split("/")[0], plannedPack: "", center: c, loadRadius: Infinity, always: true, placements: [] };
      groups.set(id, g);
    }
    // Cells below the sea surface are never seen (the ocean is opaque).
    const underSea = cz > RIM_Z ? SEA_LEVEL - 3 : -Infinity;
    for (const p of skinPlacements(ENV_MODELS, b, b.skin, underSea)) g.placements.push(p);
  }
  return [...groups.values()];
}

let cachedAreas: DressedArea[] | undefined;

/** Lay out every overworld area (not the arena) against the base world boxes. */
export function dressOverworld(base: Box[]): { areas: DressedArea[]; colliders: Box[] } {
  const specs = AREAS.filter((a) => a.id !== "arena");
  const props = specs.map((a) => layout(a, base));
  cachedAreas = [...terrain(base, specs), ...props];
  return { areas: cachedAreas, colliders: props.flatMap(colliders) };
}

/** The arena: its blocks drawn with the Dungeon Kit, plus decorative ruins (the fight's geometry stays as tuned). */
export function dressArena(base: Box[]): DressedArea[] {
  const spec = AREAS.find((a) => a.id === "arena")!;
  return [...terrain(base, [spec]), layout(spec, base)];
}

export function overworldAreas(): DressedArea[] {
  return cachedAreas ?? [];
}

/** Every model id any area may use (the asset build converts these). */
export function allDressingModels(): string[] {
  const ids = new Set<string>(allSkinModels());
  for (const a of AREAS) {
    for (const g of a.groups) g.models.forEach((m) => ids.add(m));
    for (const g of a.standIn?.groups ?? []) g.models.forEach((m) => ids.add(m));
  }
  return [...ids].sort();
}

export const AREA_PACKS = AREAS.map((a) => ({ id: a.id, name: a.name, pack: a.pack, standIn: a.standIn?.pack ?? null }));
